-- Rollback 41: kembalikan tabel struktur dan task_approvals serta 6 view. Definisi view tertanam (sama dengan ptpemaco_apam.bak41_views).
-- Jalankan: mysql --comments -u <user> -p < 42_apam_bersih_tabel_tak_terpakai_rollback.sql

RENAME TABLE ptpemaco_apam.zz_hapus_struktur TO ptpemaco_apam.struktur,
             ptpemaco_apam.zz_hapus_task_approvals TO ptpemaco_apam.task_approvals;

CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW ptpemaco_apam.`atasan_terkait_oke` AS select `ptpemaco_apam`.`a`.`employe_id` AS `employe_id`,`ptpemaco_apam`.`a`.`first_name` AS `first_name`,max((case when (`ptpemaco_apam`.`s`.`id_base` = 8) then `ptpemaco_apam`.`s`.`employe_id` end)) AS `supervisor_terkait`,max((case when (`ptpemaco_apam`.`s`.`id_base` = 7) then `ptpemaco_apam`.`s`.`employe_id` end)) AS `manager_terkait`,max((case when (`ptpemaco_apam`.`s`.`id_base` = 6) then `ptpemaco_apam`.`s`.`employe_id` end)) AS `manager_eksekutif`,max((case when (`ptpemaco_apam`.`s`.`id_base` = 4) then `ptpemaco_apam`.`s`.`employe_id` end)) AS `dir_terkait` from (`ptpemaco_apam`.`struktur_lengkap_oke` `a` left join `ptpemaco_apam`.`struktur_lengkap_oke` `s` on((`ptpemaco_apam`.`s`.`employe_id` in (`ptpemaco_apam`.`a`.`level_1`,`ptpemaco_apam`.`a`.`level_2`,`ptpemaco_apam`.`a`.`level_3`,`ptpemaco_apam`.`a`.`level_4`,`ptpemaco_apam`.`a`.`level_5`)))) group by `ptpemaco_apam`.`a`.`employe_id`,`ptpemaco_apam`.`a`.`first_name`;
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW ptpemaco_apam.`divisions_oke` AS with `puk_data` as (select `ptpemaco_apam`.`puk_emp`.`employe_id` AS `puk_nik`,(select `ptpemaco_apam`.`s`.`direct_atasan` from `ptpemaco_apam`.`struktur_lengkap_oke` `s` where ((`ptpemaco_apam`.`s`.`employe_id` = `ptpemaco_apam`.`puk_emp`.`employe_id`) and (`ptpemaco_apam`.`s`.`employe_active` = 1)) limit 1) AS `id_dir`,(select `ptpemaco_apam`.`s`.`first_name` from `ptpemaco_apam`.`struktur_lengkap_oke` `s` where ((`ptpemaco_apam`.`s`.`employe_id` = `ptpemaco_apam`.`puk_emp`.`employe_id`) and (`ptpemaco_apam`.`s`.`employe_active` = 1)) limit 1) AS `puk_nama`,`p`.`position_level` AS `position_level`,`p`.`division_id` AS `division_id` from (`ptpemaco_hr_production`.`positions` `p` join `ptpemaco_apam`.`v_active_position_holder` `puk_emp` on(((`ptpemaco_apam`.`puk_emp`.`position_id` = `p`.`id`) and (`ptpemaco_apam`.`puk_emp`.`employe_id` is not null)))) where ((`p`.`position_level` = 'Manajer') or ((`p`.`position_level` = 'Supervisor') and exists(select 1 from (`ptpemaco_hr_production`.`positions` `px` join `ptpemaco_apam`.`v_active_position_holder` `vx` on((`ptpemaco_apam`.`vx`.`position_id` = `px`.`id`))) where ((`px`.`division_id` = `p`.`division_id`) and (`px`.`position_level` = 'Manajer') and (`ptpemaco_apam`.`vx`.`employe_id` is not null))) is false))) select `d`.`id` AS `organization_id`,`d`.`board_id` AS `board_id`,`d`.`division_name` AS `organization_name`,`p`.`puk_nik` AS `PUK`,`p`.`puk_nama` AS `puk_nama`,`p`.`position_level` AS `puk_level`,`p`.`id_dir` AS `dir`,(select `ptpemaco_apam`.`a`.`first_name` from `ptpemaco_apam`.`struktur_lengkap_oke` `a` where ((`ptpemaco_apam`.`a`.`employe_id` = `p`.`id_dir`) and (`ptpemaco_apam`.`a`.`employe_active` = 1)) limit 1) AS `direktur_nama` from (`puk_data` `p` join `ptpemaco_hr_production`.`divisions` `d` on((`d`.`id` = `p`.`division_id`))) where (`d`.`id` > 10);
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW ptpemaco_apam.`gsdgsd` AS select `a`.`task_id` AS `task_id`,`a`.`task_title` AS `task_title`,`a`.`created_at` AS `created_at`,if(((select count(`z`.`task_id`) from `ptpemaco_apam`.`project_tasks` `z` where (`z`.`task_parent` = `a`.`task_id`)) = 0),`a`.`task_progress`,((select sum(`z`.`task_progress`) from `ptpemaco_apam`.`project_tasks` `z` where (`z`.`task_parent` = `a`.`task_id`)) / (select count(`z`.`task_id`) from `ptpemaco_apam`.`project_tasks` `z` where (`z`.`task_parent` = `a`.`task_id`)))) AS `progress`,`b`.`project_name` AS `project_name`,`b`.`category` AS `category`,`c`.`first_name` AS `first_name` from ((`ptpemaco_apam`.`project_tasks` `a` join `ptpemaco_apam`.`projects` `b`) join `ptpemaco_apam`.`employees` `c`) where ((`a`.`project_id` = `b`.`project_id`) and (`a`.`created_by` = `c`.`employe_id`));
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW ptpemaco_apam.`kpi_divisi` AS select `a`.`board_id` AS `board_id`,`a`.`board_name` AS `board_name`,`b`.`organization_id` AS `organization_id`,`b`.`organization_name` AS `organization_name`,((select sum(`ptpemaco_apam`.`z`.`progress`) from `ptpemaco_apam`.`list_task_final` `z` where ((`ptpemaco_apam`.`z`.`division` = `b`.`organization_id`) and (`ptpemaco_apam`.`z`.`task_parent` is null) and (year(`ptpemaco_apam`.`z`.`end_date`) = 2025))) / (select count(`ptpemaco_apam`.`z`.`task_id`) from `ptpemaco_apam`.`list_task_final` `z` where ((`ptpemaco_apam`.`z`.`division` = `b`.`organization_id`) and (`ptpemaco_apam`.`z`.`task_parent` is null) and (year(`ptpemaco_apam`.`z`.`end_date`) = 2025)))) AS `progress` from (`ptpemaco_apam`.`organizations` `b` join `ptpemaco_apam`.`board_organizations` `a`) where (`a`.`board_id` = `b`.`board_id`);
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW ptpemaco_apam.`kpi_divisi2` AS select `a`.`board_id` AS `board_id`,`a`.`board_name` AS `board_name`,`b`.`organization_id` AS `organization_id`,`b`.`organization_name` AS `organization_name`,((select sum(`ptpemaco_apam`.`z`.`progress`) from `ptpemaco_apam`.`list_task_final` `z` where ((`ptpemaco_apam`.`z`.`division` = `b`.`organization_id`) and (`ptpemaco_apam`.`z`.`task_parent` is null))) / (select count(`ptpemaco_apam`.`z`.`task_id`) from `ptpemaco_apam`.`list_task_final` `z` where ((`ptpemaco_apam`.`z`.`division` = `b`.`organization_id`) and (`ptpemaco_apam`.`z`.`task_parent` is null)))) AS `progress` from (`ptpemaco_apam`.`organizations` `b` join `ptpemaco_apam`.`board_organizations` `a`) where (`a`.`board_id` = `b`.`board_id`);
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW ptpemaco_apam.`struktur_lengkap_oke_oke` AS with `vph` as (select `ptpemaco_apam`.`v_active_position_holder`.`position_id` AS `position_id`,`ptpemaco_apam`.`v_active_position_holder`.`employe_id` AS `employe_id`,`ptpemaco_apam`.`v_active_position_holder`.`source` AS `source`,`ptpemaco_apam`.`v_active_position_holder`.`position_name_final` AS `position_name_final`,row_number() OVER (PARTITION BY `ptpemaco_apam`.`v_active_position_holder`.`employe_id` ORDER BY (case when (`ptpemaco_apam`.`v_active_position_holder`.`source` = 'PIC') then 1 when (`ptpemaco_apam`.`v_active_position_holder`.`source` = 'PS') then 2 else 3 end) )  AS `rn_main`,row_number() OVER (PARTITION BY `ptpemaco_apam`.`v_active_position_holder`.`employe_id` ORDER BY (case when (`ptpemaco_apam`.`v_active_position_holder`.`source` not in ('PIC','PS')) then 1 else 2 end),`ptpemaco_apam`.`v_active_position_holder`.`position_id` )  AS `rn_real` from `ptpemaco_apam`.`v_active_position_holder`), `vph_main` as (select `vph`.`position_id` AS `position_id`,`vph`.`employe_id` AS `employe_id`,`vph`.`source` AS `source`,`vph`.`position_name_final` AS `position_name_final`,`vph`.`rn_main` AS `rn_main`,`vph`.`rn_real` AS `rn_real` from `vph` where (`vph`.`rn_main` = 1)), `vph_real_main` as (select `vph`.`employe_id` AS `employe_id`,`vph`.`position_id` AS `position_id` from `vph` where (`vph`.`rn_real` = 1)), `hierarchy` as (select `vm`.`employe_id` AS `employe_id`,`pos`.`parent_id` AS `p1`,`p2`.`parent_id` AS `p2`,`p3`.`parent_id` AS `p3`,`p4`.`parent_id` AS `p4`,`p5`.`parent_id` AS `p5` from (((((`vph_main` `vm` join `ptpemaco_hr_production`.`positions` `pos` on((`pos`.`id` = `vm`.`position_id`))) left join `ptpemaco_hr_production`.`positions` `p2` on((`p2`.`id` = `pos`.`parent_id`))) left join `ptpemaco_hr_production`.`positions` `p3` on((`p3`.`id` = `p2`.`parent_id`))) left join `ptpemaco_hr_production`.`positions` `p4` on((`p4`.`id` = `p3`.`parent_id`))) left join `ptpemaco_hr_production`.`positions` `p5` on((`p5`.`id` = `p4`.`parent_id`)))), `atasan_final` as (select `h`.`employe_id` AS `employe_id`,`v1`.`employe_id` AS `level_1`,`v2`.`employe_id` AS `level_2`,`v3`.`employe_id` AS `level_3`,`v4`.`employe_id` AS `level_4`,`v5`.`employe_id` AS `level_5` from (((((`hierarchy` `h` left join `vph_main` `v1` on((`v1`.`position_id` = `h`.`p1`))) left join `vph_main` `v2` on((`v2`.`position_id` = `h`.`p2`))) left join `vph_main` `v3` on((`v3`.`position_id` = `h`.`p3`))) left join `vph_main` `v4` on((`v4`.`position_id` = `h`.`p4`))) left join `vph_main` `v5` on((`v5`.`position_id` = `h`.`p5`)))) select `vm`.`employe_id` AS `employe_id`,`u`.`first_name` AS `first_name`,`u`.`email` AS `email`,`ua`.`id` AS `apam_user_id`,concat('https://hr-api.ptpema.co.id/storage/photo/employee-photo/',`epd`.`photo`) AS `photo`,`vm`.`position_id` AS `position_id`,`vm`.`position_name_final` AS `position_name`,`vr`.`position_id` AS `id_position_real`,`pr`.`position_name` AS `position_real_name`,`pr`.`position_level` AS `base_name`,`bp`.`id` AS `id_base`,`bp`.`rate_sppd` AS `rate_sppd`,`bp`.`nomor_sppd` AS `nomor_sppd`,`pr`.`division_id` AS `organization_id`,`d`.`division_name` AS `organization_name`,`bo`.`id` AS `board_id`,`bo`.`board_name` AS `board_name`,`af`.`level_1` AS `level_1`,`af`.`level_2` AS `level_2`,`af`.`level_3` AS `level_3`,`af`.`level_4` AS `level_4`,`af`.`level_5` AS `level_5`,coalesce(`af`.`level_1`,`af`.`level_2`,`af`.`level_3`,`af`.`level_4`,`af`.`level_5`) AS `direct_atasan`,`ul`.`first_name` AS `direct_atasan_nama`,`ul`.`email` AS `direct_atasan_email` from ((((((((((`vph_main` `vm` left join `vph_real_main` `vr` on((`vr`.`employe_id` = `vm`.`employe_id`))) left join `ptpemaco_hr_production`.`positions` `pr` on((`pr`.`id` = `vr`.`position_id`))) left join `ptpemaco_apam`.`base_positions` `bp` on((`bp`.`base_name` = `pr`.`position_level`))) left join `ptpemaco_hr_production`.`divisions` `d` on((`d`.`id` = `pr`.`division_id`))) left join `ptpemaco_hr_production`.`board_organizations` `bo` on((`bo`.`id` = `d`.`board_id`))) left join `atasan_final` `af` on((`af`.`employe_id` = `vm`.`employe_id`))) left join `ptpemaco_hr_production`.`users` `u` on((`u`.`employe_id` = `vm`.`employe_id`))) left join `ptpemaco_apam`.`users` `ua` on((`ua`.`email` = `u`.`email`))) left join `ptpemaco_hr_production`.`employee_personal_data` `epd` on((`epd`.`employe_id` = `vm`.`employe_id`))) left join `ptpemaco_hr_production`.`users` `ul` on((`ul`.`employe_id` = coalesce(`af`.`level_1`,`af`.`level_2`,`af`.`level_3`,`af`.`level_4`,`af`.`level_5`))));

-- Laporan: tabel_kembali = 2, view_kembali = 6
SELECT
  (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = 'ptpemaco_apam' AND table_name IN ('struktur', 'task_approvals')) AS tabel_kembali,
  (SELECT COUNT(*) FROM information_schema.views WHERE table_schema = 'ptpemaco_apam' AND table_name IN ('atasan_terkait_oke', 'divisions_oke', 'gsdgsd', 'kpi_divisi', 'kpi_divisi2', 'struktur_lengkap_oke_oke')) AS view_kembali;
-- Tabel bak41_views dibiarkan; hapus manual setelah stabil.
